// Phân loại một trang theo đặc điểm của nó (mô phỏng quy tắc của Cache Components)
function classify(page) {
  const dynamic = page.usesCookies || page.usesHeaders || page.usesSearchParams || page.uncachedFetch;
  if (!dynamic) return "tĩnh (dựng sẵn lúc build)";
  if (page.hasSuspense) return "vỏ tĩnh + truyền dần phần động";
  return "chặn: cần <Suspense> quanh phần động";
}

console.log(classify({}));
console.log(classify({ usesCookies: true, hasSuspense: true }));
console.log(classify({ uncachedFetch: true }));

