function isShortLived(c) {
  return c.profile === "seconds" || c.revalidate === 0 || (c.expire !== undefined && c.expire < 300);
}
console.log([
  isShortLived({ profile: "seconds" }),
  isShortLived({ revalidate: 0 }),
  isShortLived({ expire: 60 }),
  isShortLived({ profile: "hours" }),
].join(","));

