function strategy(r) {
  if (r.perUser) return "dynamic (Suspense)";
  if (r.freshness === "never") return "static";
  if (r.freshness === "minutes") return "cache (minutes)";
  return "dynamic (Suspense)";
}
console.log([
  strategy({ perUser: false, freshness: "never" }),
  strategy({ perUser: false, freshness: "minutes" }),
  strategy({ perUser: true, freshness: "never" }),
].join(" | "));
